// before: Booking had `startDate`, `endDate`, and overlaps()/nights()
// after:
 class DateRange {
   start: Date = new Date();
   end: Date = new Date();
   get start_() { return this.start; }
   set start_(d: Date) { this.start = d; }
   get end_() { return this.end; }
   set end_(d: Date) { this.end = d; }
 }

 class Booking {
   range = new DateRange();
   // overlaps() and nights() were left here, still on Booking:
   overlaps(other: Booking): boolean {
     return this.range.start < other.range.end && other.range.start < this.range.end;
   }
   nights(): number {
     return (this.range.end.getTime() - this.range.start.getTime()) / 86400000;
   }
 }
